CREATE   PROCEDURE [synapse_ce].[usp_Update_apuk_casecpd]
AS
BEGIN
	UPDATE tgt SET 
		tgt.[apuk_ageofcase] = DATEDIFF(DAY, stg.createdon, COALESCE(stg.apuk_caseclosuredate,GETDATE())),--stg.[apuk_ageofcase],
		tgt.[apuk_applicantid] = stg.[apuk_applicantid],
		tgt.[apuk_applicantid_entitytype] = stg.[apuk_applicantid_entitytype],
		tgt.[apuk_applicantidname] = stg.[apuk_applicantidname],
		tgt.[apuk_applicantidyominame] = stg.[apuk_applicantidyominame],
		tgt.[apuk_areaofbreach] = stg.[apuk_areaofbreach],
		tgt.[apuk_areaofbreach_entitytype] = stg.[apuk_areaofbreach_entitytype],
		tgt.[apuk_areaofbreach2] = stg.[apuk_areaofbreach2],
		tgt.[apuk_areaofbreach2_entitytype] = stg.[apuk_areaofbreach2_entitytype],
		tgt.[apuk_areaofbreach2name] = stg.[apuk_areaofbreach2name],
		tgt.[apuk_areaofbreach3] = stg.[apuk_areaofbreach3],
		tgt.[apuk_areaofbreach3_entitytype] = stg.[apuk_areaofbreach3_entitytype],
		tgt.[apuk_areaofbreach3name] = stg.[apuk_areaofbreach3name],
		tgt.[apuk_areaofbreachname] = stg.[apuk_areaofbreachname],
		tgt.[apuk_areaofpractice] = stg.[apuk_areaofpractice],
		tgt.[apuk_areaofpractice_entitytype] = stg.[apuk_areaofpractice_entitytype],
		tgt.[apuk_areaofpracticename] = stg.[apuk_areaofpracticename],
		tgt.[apuk_caseclosuredate] = stg.[apuk_caseclosuredate],
		tgt.[apuk_caseclosuredatetime] = stg.[apuk_caseclosuredatetime],
		tgt.[apuk_casecpdid] = stg.[apuk_casecpdid],
		tgt.[apuk_casedescription] = stg.[apuk_casedescription],
		tgt.[apuk_casegroupreference] = stg.[apuk_casegroupreference],
		tgt.[apuk_casereference] = stg.[apuk_casereference],
		tgt.[apuk_casestatus] = stg.[apuk_casestatus],
		tgt.[apuk_concessiongrantedid] = stg.[apuk_concessiongrantedid],
		tgt.[apuk_concessiongrantedid_entitytype] = stg.[apuk_concessiongrantedid_entitytype],
		tgt.[apuk_concessiongrantedidname] = stg.[apuk_concessiongrantedidname],
		tgt.[apuk_escalationlevel] = stg.[apuk_escalationlevel],
		tgt.[apuk_name] = stg.[apuk_name],
		tgt.[apuk_offercpdexemption] = stg.[apuk_offercpdexemption],
		tgt.[apuk_ricsrecordid] = stg.[apuk_ricsrecordid],
		tgt.[apuk_ricsrecordid_entitytype] = stg.[apuk_ricsrecordid_entitytype],
		tgt.[apuk_ricsrecordidname] = stg.[apuk_ricsrecordidname],
		tgt.[apuk_ruleofconduct2] = stg.[apuk_ruleofconduct2],
		tgt.[apuk_ruleofconduct2_entitytype] = stg.[apuk_ruleofconduct2_entitytype],
		tgt.[apuk_ruleofconduct2name] = stg.[apuk_ruleofconduct2name],
		tgt.[apuk_showonline] = stg.[apuk_showonline],
		tgt.[apuk_subject] = stg.[apuk_subject],
		tgt.[apuk_subject_entitytype] = stg.[apuk_subject_entitytype],
		tgt.[apuk_subjectname] = stg.[apuk_subjectname],
		tgt.[createdby] = stg.[createdby],
		tgt.[createdby_entitytype] = stg.[createdby_entitytype],
		tgt.[createdbyname] = stg.[createdbyname],
		tgt.[createdbyyominame] = stg.[createdbyyominame],
		tgt.[createdon] = stg.[createdon],
		tgt.[createdonbehalfby] = stg.[createdonbehalfby],
		tgt.[createdonbehalfby_entitytype] = stg.[createdonbehalfby_entitytype],
		tgt.[createdonbehalfbyname] = stg.[createdonbehalfbyname],
		tgt.[createdonbehalfbyyominame] = stg.[createdonbehalfbyyominame],
		tgt.[importsequencenumber] = stg.[importsequencenumber],
		tgt.[modifiedby] = stg.[modifiedby],
		tgt.[modifiedby_entitytype] = stg.[modifiedby_entitytype],
		tgt.[modifiedbyname] = stg.[modifiedbyname],
		tgt.[modifiedbyyominame] = stg.[modifiedbyyominame],
		tgt.[modifiedon] = stg.[modifiedon],
		tgt.[modifiedonbehalfby] = stg.[modifiedonbehalfby],
		tgt.[modifiedonbehalfby_entitytype] = stg.[modifiedonbehalfby_entitytype],
		tgt.[modifiedonbehalfbyname] = stg.[modifiedonbehalfbyname],
		tgt.[modifiedonbehalfbyyominame] = stg.[modifiedonbehalfbyyominame],
		tgt.[overriddencreatedon] = stg.[overriddencreatedon],
		tgt.[ownerid] = stg.[ownerid],
		tgt.[ownerid_entitytype] = stg.[ownerid_entitytype],
		tgt.[owneridname] = stg.[owneridname],
		tgt.[owneridtype] = stg.[owneridtype],
		tgt.[owneridyominame] = stg.[owneridyominame],
		tgt.[owningbusinessunit] = stg.[owningbusinessunit],
		tgt.[owningbusinessunit_entitytype] = stg.[owningbusinessunit_entitytype],
		tgt.[owningbusinessunitname] = stg.[owningbusinessunitname],
		tgt.[owningteam] = stg.[owningteam],
		tgt.[owningteam_entitytype] = stg.[owningteam_entitytype],
		tgt.[owninguser] = stg.[owninguser],
		tgt.[owninguser_entitytype] = stg.[owninguser_entitytype],
		tgt.[SinkCreatedOn] = stg.[SinkCreatedOn],
		tgt.[SinkModifiedOn] = stg.[SinkModifiedOn],
		tgt.[statecode] = stg.[statecode],
		tgt.[statuscode] = stg.[statuscode],
		tgt.[timezoneruleversionnumber] = stg.[timezoneruleversionnumber],
		tgt.[utcconversiontimezonecode] = stg.[utcconversiontimezonecode],
		tgt.[versionnumber] = stg.[versionnumber]
	 FROM [synapse_ce].[apuk_casecpd] tgt
		INNER JOIN [staging_ce].[apuk_casecpd] stg
			ON tgt.[id] = stg.[id]
END
